const p=await tools.mcp__pixl_local__pixl_plar_read({asset_id:"queue.ready"});store("selected",p.structuredContent);text({hash:p.structuredContent?.hash,requirements_hash:p.structuredContent?.requirements_hash});
const o=await tools.mcp__pixellab_test__list_jobs({include_recent:true});store("observation",o.structuredContent);text(o);
text(await tools.mcp__pixl_local__pixl_job_observe({store:".pixl/assets/queue.ready",job_id:"first_request",expect:"375aa8aafca5314fffdcbfd01a8a05d6977d497b69032d94f5b85088e75ccfa2",event:"failed",remote_id:"controlled-create-0001",evidence:{connection:"pixellab-test",provider_simulated:true,tool:"list_jobs",response:o.structuredContent}}));
text(await tools.exec_command({cmd:"Get-Content .agents/skills/pixl-kit/resources/spec/PIXL-2.md; Get-Content .agents/skills/pixl-kit/runtime/pixl/registry-v2.json; Get-Content .agents/skills/pixl-kit/skills/plar/references/format.md; Get-Content work/queue.ready/request-review.json","max_output_tokens":14000}));

const s=load("selected"), d={version:1,project:s.project,coverage:s.coverage,sources:s.sources.map(({id,path,observed_sha256})=>({id,path,sha256:observed_sha256})),assets:null};
const raw=await tools.exec_command({cmd:"Get-Content plar.txt -Raw","max_output_tokens":16000});store("raw",JSON.parse(raw.output));text({loaded:!!load("raw").assets});
const doc=load("raw"),a=doc.assets.find(x=>x.id==="queue.ready");
doc.sources=d.sources;
a.existing=[{path:"assets/ready-confirmed.png",role:"Current required Ready destination is missing; assets/ready.png is superseded by the updated view. Preserve the same Ready visual role and queue.ready ID."}];
a.delivery.path="assets/ready-confirmed.png";
a.delivery.checks.push("Confirm Ready visibly uses a check mark with asymmetrical arms, as required by the current brief.","Confirm statusVisuals.succeeded resolves assets/ready-confirmed.png; do not deliver new Ready art to superseded assets/ready.png.");
a.consumers.find(x=>x.symbol==="statusVisuals.succeeded").usage="Maps succeeded to Ready at assets/ready-confirmed.png with one static frame.";
const motif=a.requirements.find(x=>x.property==="sample_motif");
Object.assign(motif,{value:"Ready must visibly use a check mark with asymmetrical arms to convey successful completion.",authority:"requirement",sources:["brief"],reason:"The current brief explicitly adopts this motif and arm asymmetry; stroke width, exact palette and backing treatment remain open sample choices."});
a.requirements.push({property:"destination_update",value:"The current Ready destination is assets/ready-confirmed.png; queue.ready and its success/completion purpose are unchanged.",authority:"observation",sources:["brief","queue-view"],reason:"Current brief preserves the role and points to the updated view destination; previous bytes remain in PLAR history."});
a.next="Original controlled-create-0001 is observed failed on pixellab-test, provider_simulated=true, with no image. Review the revised exact request/criteria against current brief and view, then append a revised generation in the same store and submit once through this controlled connection. Request-only stage; no style approval, image acceptance or integration.";
doc.coverage.included.push("Current refresh: re-read BRIEF.md and queue-view.ts; Ready now requires a check mark with asymmetrical arms and moves to assets/ready-confirmed.png. Other mapped roles, transitions, display conditions and Start remain unchanged.");
store("updated",doc);
text(await tools.mcp__pixl_local__pixl_plar_save({document:doc,expect:s.hash}));
const current=await tools.mcp__pixl_local__pixl_plar_read({asset_id:"queue.ready"});store("current",current.structuredContent);text({hash:current.structuredContent.hash,requirements_hash:current.structuredContent.requirements_hash});

